//! **Which way the cursor's paragraph runs, and the arrow keys it swaps**:
//! terminal-wg's `?1243` (`[[source: terminal-wg-bidi-arrow-key-swapping]]`),
//! "the sequences generated by the Left and Right arrows are swapped
//! whenever the cursor is inside a RTL paragraph. (In case of
//! autodetection, it's the autodetected direction that matters and not the
//! specified fallback.)" -- and "Note that Home and End should not be
//! swapped".
//!
//! **The direction is the one the paragraph is drawn in**, read the way the
//! renderer reads it: with BDSM reset, its character path, right to left
//! only where SCP or SPD chose it; with BDSM set, the level its properties
//! give it ([`baud_domain::LineBidi::paragraph`]) over its text, the rows a
//! soft wrap joins and the history's lines above them, a cell's attached
//! characters included; and on a table row, a row holding a Box Drawing
//! character, the cell between two rules the cursor is in, each a
//! paragraph of its own (UAX #9 section 3; Jev, CELL, 0.98/0.98). A
//! cursor on a rule is in the cell before it, as P1 keeps a paragraph
//! separator with the paragraph it ends, and one past a table row's text
//! is in no cell: the renderer draws those cells left to right where they
//! are, and so the keys there are as pressed.
//!
//! **The press decides**: the draft swaps "conditionally to the cursor
//! being inside an RTL paragraph at the time the key is pressed"
//! (`[[source: terminal-wg-bidi-escape-sequences]]`), so a key's repeat
//! and release take the decision its press made
//! ([`baud_domain::HeldArrows`]), one bit per key, and name the key the
//! press named though the cursor has moved since; one with no press
//! recorded goes as pressed.
//!
//! **What it costs**: nothing until a Left or Right key arrives, then at a
//! press with the mode set two walks of the cursor's paragraph at most,
//! and four bits stored.

use baud_domain::{
    ArrowSwap, BidiDirection, BidiSupport, CharacterPath, Col, FirstStrongScan, KeyCode, KeyEvent,
    KeyEventKind, KeySwap, KeypadKey, Row, Rows, Wrap, is_table_rule,
};

use crate::term::Term;

/// One step of a walk of a paragraph's text.
#[derive(Clone, Copy)]
enum Step {
    /// A character the layout reads, and whether it is a rule.
    Char(char, Rule),
    /// The cursor's cell begins here.
    Cursor,
    /// The cursor's cell is past its row's text.
    CursorPast,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Rule {
    Yes,
    No,
}

/// Where a paragraph's rows are: how many of the history's lines it
/// begins in, and its first and last screen rows.
#[derive(Clone, Copy)]
struct Span {
    hist: Rows,
    top: Row,
    bot: Row,
}

impl Term<'_> {
    /// **Which way the paragraph holding screen row `r`'s column `c` runs**,
    /// as it is drawn: the direction `?1243` swaps the arrow keys by.
    pub fn paragraph_direction(&self, r: Row, c: Col) -> BidiDirection {
        let vp = self.view(Rows::ZERO);
        if r.index() >= vp.rows().index() {
            return BidiDirection::Ltr;
        }
        let bidi = vp.bidi(r);
        if self.bidi_support() == BidiSupport::Explicit {
            return match bidi.path() {
                CharacterPath::RightToLeft => BidiDirection::Rtl,
                _ => BidiDirection::Ltr,
            };
        }
        let mut top = r.index();
        while top > 0 && vp.wrapped(Row::from_index(top - 1)) == Wrap::Continues {
            top -= 1;
        }
        let mut hist = 0;
        if top == 0 {
            loop {
                let want = Rows::of_index(hist + 1);
                if self.looking_back(want) != want
                    || self.view(want).wrapped(Row::ZERO) != Wrap::Continues
                {
                    break;
                }
                hist += 1;
            }
        }
        let last = vp.rows().index() - 1;
        let mut bot = r.index();
        while bot < last && vp.wrapped(Row::from_index(bot)) == Wrap::Continues {
            bot += 1;
        }
        let span = Span {
            hist: Rows::of_count(hist),
            top: Row::from_index(top),
            bot: Row::from_index(bot),
        };
        let dir = bidi.paragraph();
        // The first walk: the paragraph's direction, whether it holds a
        // rule, and the last rule before the cursor's cell.
        let (mut i, mut at, mut before, mut table) = (0usize, None, None, Rule::No);
        let mut past = false;
        let mut whole = FirstStrongScan::new(dir);
        let mut found = None;
        self.walk(span, (r, c), |s| match s {
            Step::Cursor => at = Some(i),
            Step::CursorPast => {
                at = Some(i);
                past = true;
            }
            Step::Char(ch, rule) => {
                if rule == Rule::Yes {
                    table = Rule::Yes;
                    if at.is_none() {
                        before = Some(i);
                    }
                }
                if found.is_none() {
                    found = whole.step(ch);
                }
                i += 1;
            }
        });
        if table == Rule::No {
            return found.unwrap_or_else(|| whole.end());
        }
        if past {
            return BidiDirection::Ltr;
        }
        // A table row, walked again: the cell from the rule before the
        // cursor to the next.
        let start = before.map_or(0, |k| k + 1);
        let (mut j, mut ended) = (0usize, false);
        let mut cell = FirstStrongScan::new(dir);
        let mut found = None;
        self.walk(span, (r, c), |s| {
            if let Step::Char(ch, rule) = s {
                if j >= start && !ended && found.is_none() {
                    match rule {
                        Rule::Yes => ended = true,
                        Rule::No => found = cell.step(ch),
                    }
                }
                j += 1;
            }
        });
        found.unwrap_or_else(|| cell.end())
    }

    /// Each character of the paragraph `span` covers, in the order the
    /// layout reads them, with [`Step::Cursor`] where `cursor`'s cell (a
    /// screen row and column) begins, or at its row's text's end when the
    /// cell is past it.
    fn walk(&self, span: Span, cursor: (Row, Col), mut f: impl FnMut(Step)) {
        let vp = self.view(Rows::ZERO);
        let rows = (0..span.hist.index())
            .rev()
            .map(|k| (None, self.view(Rows::of_index(k + 1)).row(Row::ZERO)))
            .chain(
                (span.top.index()..=span.bot.index())
                    .map(|y| (Some(Row::from_index(y)), vp.row(Row::from_index(y)))),
            );
        for (y, cells) in rows {
            let end = cells
                .iter()
                .rposition(|x| !x.content.is_empty())
                .map_or(0, |k| k + 1);
            let here = y == Some(cursor.0);
            for (x, &cell) in cells[..end].iter().enumerate() {
                if here && x == cursor.1.index() {
                    f(Step::Cursor);
                }
                if cell.content.is_wide_tail() || cell.content.is_empty() {
                    continue;
                }
                let base = self
                    .base_of(cell)
                    .drawn()
                    .as_codepoint()
                    .and_then(|v| char::from_u32(v.value()))
                    .unwrap_or('\u{FFFD}');
                let marked = cell.flags.is_marked();
                let rule = match !marked && is_table_rule(base) {
                    true => Rule::Yes,
                    false => Rule::No,
                };
                f(Step::Char(base, rule));
                if marked {
                    for m in self.cluster_marks(cell).filter_map(char::from_u32) {
                        f(Step::Char(m, Rule::No));
                    }
                }
            }
            if here && cursor.1.index() >= end {
                f(Step::CursorPast);
            }
        }
    }

    /// `e` with Left and Right exchanged where `?1243` was set and the
    /// cursor's paragraph ran right to left when the key was pressed, the
    /// decision a press records and its repeats and release take; any
    /// other key as it is.
    pub(crate) fn arrows_swapped(&mut self, e: KeyEvent) -> KeyEvent {
        let swapped = match e.code {
            KeyCode::Left => KeyCode::Right,
            KeyCode::Right => KeyCode::Left,
            KeyCode::Keypad(KeypadKey::Left) => KeyCode::Keypad(KeypadKey::Right),
            KeyCode::Keypad(KeypadKey::Right) => KeyCode::Keypad(KeypadKey::Left),
            _ => return e,
        };
        let swap = match e.kind {
            KeyEventKind::Press => {
                let swap = match self.cold.arrows {
                    ArrowSwap::Off => KeySwap::AsPressed,
                    ArrowSwap::On => {
                        let (r, c) = self.cursor();
                        match self.paragraph_direction(r, c) {
                            BidiDirection::Rtl => KeySwap::Swapped,
                            BidiDirection::Ltr => KeySwap::AsPressed,
                        }
                    }
                };
                self.cold.held_arrows.press(e.code, swap);
                swap
            }
            KeyEventKind::Repeat => self.cold.held_arrows.decided(e.code),
            KeyEventKind::Release => self.cold.held_arrows.release(e.code),
        };
        match swap {
            KeySwap::Swapped => KeyEvent { code: swapped, ..e },
            KeySwap::AsPressed => e,
        }
    }
}
